mapper.select:
SELECT id, title, selected_kb_ids AS "selectedKbIdsRaw", last_message_at AS "lastMessageAt", created_at AS "createdAt", updated_at AS "updatedAt" FROM kb_conversation WHERE deleted_at IS NULL AND user_id = #{userId}
AND (last_message_at, id) < (#{cursorTime}, #{cursorId})
ORDER BY last_message_at DESC, id DESC LIMIT #{limit}

mapper.update:
UPDATE kb_conversation
   SET last_message_at = NOW(), updated_at = NOW()
 WHERE id = #{id}
